public static int CountEven(Stack<int> s)
{
    // סופרים את הזוגיים בעזרת מחסנית עזר
    Stack<int> temp = new Stack<int>();
    int count = 0;
    while (!s.IsEmpty())
    {
        int x = s.Pop();
        if (x % 2 == 0)
        {
            count++;
        }
        temp.Push(x);
    }
    while (!temp.IsEmpty())
    {
        s.Push(temp.Pop());
    }
    return count;
}

public static void RemoveAll(Stack<int> s, int x)
{
    Stack<int> temp = new Stack<int>();
    while (!s.IsEmpty())
    {
        int v = s.Pop();
        if (v != x)
        {
            temp.Push(v);
        }
    }
    while (!temp.IsEmpty())
    {
        s.Push(temp.Pop());
    }
}

public static bool IsSquare(int[,] mat)
{
    return mat.GetLength(0) == mat.GetLength(1);
}

